{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE TEMP TABLE Cocoblu_Inventory_Base AS SELECT CAST(startDate AS DATE) AS DATA_FETCH_DATE, asin AS ASIN, IFNULL(SAFE_CAST(sellableOnHandInventoryUnits AS FLOAT64), 0) AS AVAILABLE_INVENTORY, IFNULL(SAFE_CAST(unsellableOnHandInventoryUnits AS FLOAT64), 0) AS UNSELLABLE_INVENTORY, IFNULL(SAFE_CAST(aged90PlusDaysSellableInventoryUnits AS FLOAT64), 0) AS AGED_90D_UNITS, IFNULL(SAFE_CAST(openPurchaseOrderUnits AS FLOAT64), 0) AS OPEN_PO_UNITS, IFNULL(SAFE_CAST(unfilledCustomerOrderedUnits AS FLOAT64), 0) AS UNFILLED_DEMAND_UNITS, SAFE_CAST(JSON_EXTRACT_SCALAR(sellableOnHandInventoryCost, \'$.amount\') AS FLOAT64) AS SELLABLE_INVENTORY_VALUE, SAFE_CAST(JSON_EXTRACT_SCALAR(aged90PlusDaysSellableInventoryCost, \'$.amount\') AS FLOAT64) AS AGED_90D_INVENTORY_VALUE FROM `Maplemonk.Zouk_AVP_GET_VENDOR_INVENTORY_REPORT` ; CREATE TEMP TABLE Cocoblu_Sales_Daily AS WITH sales_agg AS ( SELECT DATE(DATETIME(TIMESTAMP(endTime), \"Asia/Kolkata\")) AS ORDER_DATE, asin AS ASIN, SUM(IFNULL(SAFE_CAST(orderedUnits AS INT64), 0)) AS QUANTITY, SUM(IFNULL(SAFE_CAST(orderedRevenue AS FLOAT64), 0)) AS GMV FROM `MapleMonk.ZOUK_AVP_GET_VENDOR_REAL_TIME_SALES_REPORT` GROUP BY 1, 2 ) SELECT * FROM sales_agg; CREATE TEMP TABLE Cocoblu_Pre_DRR AS SELECT SD.ORDER_DATE AS DATE, SD.ASIN, SD.QUANTITY, CASE WHEN IFNULL(SD.QUANTITY, 0) > 0 THEN 1 ELSE 0 END AS DRR_FLAG FROM Cocoblu_Sales_Daily SD WHERE SD.ORDER_DATE >= DATE_SUB( (SELECT MAX(CAST(startDate AS DATE)) FROM `Maplemonk.Zouk_AVP_GET_VENDOR_INVENTORY_REPORT`), INTERVAL 91 DAY ); CREATE TEMP TABLE Cocoblu_Final_DRR AS SELECT PD.DATE, PD.ASIN, SUM( CASE WHEN PDR.DRR_FLAG = 1 THEN IFNULL(PDR.QUANTITY, 0) ELSE 0 END ) AS DRR_QUANTITY, SUM(IFNULL(PDR.DRR_FLAG, 0)) AS DRR_DAYS FROM Cocoblu_Pre_DRR PD LEFT JOIN Cocoblu_Pre_DRR PDR ON PD.ASIN = PDR.ASIN AND DATE_DIFF(PD.DATE, PDR.DATE, DAY) <= 90 AND DATE_DIFF(PD.DATE, PDR.DATE, DAY) > 0 GROUP BY 1, 2; CREATE TEMP TABLE Cocoblu_Product_Master AS SELECT * FROM ( SELECT LOWER(TRIM(channel_product_id)) AS ASIN_KEY, COMMONSKU AS COMMONSKU, NAME AS PRODUCT_NAME, BRAND AS BRAND, CATEGORY AS CATEGORY, CATEGORY_CODE AS CATEGORY_CODE, collection AS COLLECTION, PRODUCT_TYPE AS PRODUCT_TYPE, PRODUCT_BUCKET AS PRODUCT_BUCKET, Type AS SKU_TYPE, CAST(colour AS STRING) AS COLOR, CAST(SIZE AS STRING) AS SIZE, IFNULL(SAFE_CAST(MRP AS FLOAT64), 0.0) AS MRP, IFNULL(SAFE_CAST(BAU_Online AS FLOAT64), 0.0) AS BAU_ONLINE, ROW_NUMBER() OVER ( PARTITION BY LOWER(TRIM(channel_product_id)) ORDER BY CASE WHEN commonsku IS NOT NULL AND commonsku != \'\' THEN 0 ELSE 1 END ASC, CASE WHEN NAME IS NOT NULL THEN 0 ELSE 1 END ASC ) AS rw FROM `maplemonk.FINAL_SKU_MASTER` WHERE channel_product_id IS NOT NULL AND TRIM(channel_product_id) != \'\' ) WHERE rw = 1; CREATE TEMP TABLE Cocoblu_Sales_Windowed AS WITH base AS ( SELECT INV.DATA_FETCH_DATE, INV.ASIN, INV.AVAILABLE_INVENTORY, INV.UNSELLABLE_INVENTORY, INV.AGED_90D_UNITS, INV.OPEN_PO_UNITS, INV.UNFILLED_DEMAND_UNITS, INV.SELLABLE_INVENTORY_VALUE, INV.AGED_90D_INVENTORY_VALUE, COALESCE(PM.COMMONSKU, INV.ASIN) AS COMMONSKU, COALESCE(PM.PRODUCT_NAME, \'\') AS PRODUCT_NAME, COALESCE(PM.CATEGORY, \'\') AS CATEGORY, COALESCE(PM.CATEGORY_CODE, \'\') AS CATEGORY_CODE, COALESCE(PM.COLLECTION, \'\') AS COLLECTION, COALESCE(PM.PRODUCT_TYPE, \'\') AS PRODUCT_TYPE, COALESCE(PM.PRODUCT_BUCKET, \'\') AS PRODUCT_BUCKET, COALESCE(PM.SKU_TYPE, \'\') AS SKU_TYPE, COALESCE(PM.COLOR, \'\') AS COLOR, COALESCE(PM.SIZE, \'\') AS SIZE, COALESCE(PM.MRP, 0.0) AS MRP, COALESCE(PM.BAU_ONLINE, 0.0) AS BAU_ONLINE, CASE WHEN LOWER(TRIM(PM.BRAND)) LIKE \'%zouk%\' THEN \'ZOUK\' WHEN LOWER(TRIM(PM.BRAND)) LIKE \'%everpret%\' THEN \'EVERPRET\' WHEN LOWER(TRIM(PM.BRAND)) LIKE \'%doto%\' THEN \'DOTO\' WHEN LOWER(TRIM(PM.BRAND)) LIKE \'%1991%\' THEN \'1991\' ELSE UPPER(TRIM(COALESCE(PM.BRAND, \'\'))) END AS BRAND, CASE WHEN PM.ASIN_KEY IS NOT NULL THEN \'asin_match\' ELSE \'no_match\' END AS PM_MATCH_TYPE, SD.ORDER_DATE, SD.QUANTITY, SD.GMV FROM Cocoblu_Inventory_Base INV LEFT JOIN Cocoblu_Product_Master PM ON LOWER(TRIM(INV.ASIN)) = PM.ASIN_KEY LEFT JOIN Cocoblu_Sales_Daily SD ON INV.ASIN = SD.ASIN ) SELECT DATA_FETCH_DATE, ASIN, AVAILABLE_INVENTORY, ANY_VALUE(UNSELLABLE_INVENTORY) AS UNSELLABLE_INVENTORY, ANY_VALUE(AGED_90D_UNITS) AS AGED_90D_UNITS, ANY_VALUE(OPEN_PO_UNITS) AS OPEN_PO_UNITS, ANY_VALUE(UNFILLED_DEMAND_UNITS) AS UNFILLED_DEMAND_UNITS, ANY_VALUE(SELLABLE_INVENTORY_VALUE) AS SELLABLE_INVENTORY_VALUE, ANY_VALUE(AGED_90D_INVENTORY_VALUE) AS AGED_90D_INVENTORY_VALUE, ANY_VALUE(COMMONSKU) AS COMMONSKU, ANY_VALUE(PRODUCT_NAME) AS PRODUCT_NAME, ANY_VALUE(CATEGORY) AS CATEGORY, ANY_VALUE(CATEGORY_CODE) AS CATEGORY_CODE, ANY_VALUE(COLLECTION) AS COLLECTION, ANY_VALUE(PRODUCT_TYPE) AS PRODUCT_TYPE, ANY_VALUE(PRODUCT_BUCKET) AS PRODUCT_BUCKET, ANY_VALUE(SKU_TYPE) AS SKU_TYPE, ANY_VALUE(COLOR) AS COLOR, ANY_VALUE(SIZE) AS SIZE, ANY_VALUE(MRP) AS MRP, ANY_VALUE(BAU_ONLINE) AS BAU_ONLINE, ANY_VALUE(BRAND) AS BRAND, ANY_VALUE(PM_MATCH_TYPE) AS PM_MATCH_TYPE, SUM(CASE WHEN DATE_DIFF(DATA_FETCH_DATE, ORDER_DATE, DAY) = 1 THEN IFNULL(QUANTITY, 0) ELSE 0 END) AS SOLD_QTY_LAST_DAY, SUM(CASE WHEN DATE_DIFF(DATA_FETCH_DATE, ORDER_DATE, DAY) = 1 THEN IFNULL(GMV, 0) ELSE 0 END) AS GMV_LAST_DAY, SUM(CASE WHEN DATE_DIFF(DATA_FETCH_DATE, ORDER_DATE, DAY) BETWEEN 1 AND 7 THEN IFNULL(QUANTITY, 0) ELSE 0 END) AS SOLD_QTY_7D, SUM(CASE WHEN DATE_DIFF(DATA_FETCH_DATE, ORDER_DATE, DAY) BETWEEN 1 AND 7 THEN IFNULL(GMV, 0) ELSE 0 END) AS GMV_7D, SUM(CASE WHEN DATE_DIFF(DATA_FETCH_DATE, ORDER_DATE, DAY) BETWEEN 1 AND 14 THEN IFNULL(QUANTITY, 0) ELSE 0 END) AS SOLD_QTY_14D, SUM(CASE WHEN DATE_DIFF(DATA_FETCH_DATE, ORDER_DATE, DAY) BETWEEN 1 AND 14 THEN IFNULL(GMV, 0) ELSE 0 END) AS GMV_14D, SUM(CASE WHEN DATE_DIFF(DATA_FETCH_DATE, ORDER_DATE, DAY) BETWEEN 1 AND 30 THEN IFNULL(QUANTITY, 0) ELSE 0 END) AS SOLD_QTY_30D, SUM(CASE WHEN DATE_DIFF(DATA_FETCH_DATE, ORDER_DATE, DAY) BETWEEN 1 AND 30 THEN IFNULL(GMV, 0) ELSE 0 END) AS GMV_30D, SUM(CASE WHEN DATE_DIFF(DATA_FETCH_DATE, ORDER_DATE, DAY) BETWEEN 1 AND 56 THEN IFNULL(QUANTITY, 0) ELSE 0 END) AS SOLD_QTY_56D, SUM(CASE WHEN DATE_DIFF(DATA_FETCH_DATE, ORDER_DATE, DAY) BETWEEN 1 AND 56 THEN IFNULL(GMV, 0) ELSE 0 END) AS GMV_56D, SUM(CASE WHEN DATE_TRUNC(ORDER_DATE, MONTH) = DATE_TRUNC(DATA_FETCH_DATE, MONTH) AND ORDER_DATE < DATA_FETCH_DATE THEN IFNULL(QUANTITY, 0) ELSE 0 END) AS SOLD_QTY_MTD, SUM(CASE WHEN DATE_TRUNC(ORDER_DATE, MONTH) = DATE_TRUNC(DATA_FETCH_DATE, MONTH) AND ORDER_DATE < DATA_FETCH_DATE THEN IFNULL(GMV, 0) ELSE 0 END) AS GMV_MTD FROM base GROUP BY 1, 2, 3; CREATE OR REPLACE TABLE `maplemonk.cocoblu_inventory_fact_Items` AS WITH DOH_BASE AS ( SELECT SW.*, IFNULL(FD.DRR_QUANTITY, 0) AS DRR_QUANTITY_90D, IFNULL(FD.DRR_DAYS, 0) AS DRR_DAYS_90D, CASE WHEN IFNULL(FD.DRR_DAYS, 0) > 0 THEN ROUND(SAFE_DIVIDE(FD.DRR_QUANTITY, FD.DRR_DAYS), 2) ELSE 0 END AS DRR, CASE WHEN SW.AVAILABLE_INVENTORY > 1 THEN 1 ELSE 0 END AS AVAILABILITY FROM Cocoblu_Sales_Windowed SW LEFT JOIN Cocoblu_Final_DRR FD ON CAST(SW.DATA_FETCH_DATE AS DATE) = CAST(FD.DATE AS DATE) AND SW.ASIN = FD.ASIN ) SELECT DATA_FETCH_DATE, ASIN, COMMONSKU, PM_MATCH_TYPE, PRODUCT_NAME, BRAND, CATEGORY, CATEGORY_CODE, COLLECTION, PRODUCT_TYPE, PRODUCT_BUCKET, SKU_TYPE, COLOR, SIZE, MRP, BAU_ONLINE, AVAILABLE_INVENTORY, UNSELLABLE_INVENTORY, AGED_90D_UNITS, OPEN_PO_UNITS, UNFILLED_DEMAND_UNITS, SELLABLE_INVENTORY_VALUE, AGED_90D_INVENTORY_VALUE, AVAILABILITY, SOLD_QTY_LAST_DAY, GMV_LAST_DAY, SOLD_QTY_7D, GMV_7D, SOLD_QTY_14D, GMV_14D, SOLD_QTY_30D, GMV_30D, SOLD_QTY_56D, GMV_56D, SOLD_QTY_MTD, GMV_MTD, DRR_QUANTITY_90D, DRR_DAYS_90D, DRR, CASE WHEN DRR = 0 THEN NULL ELSE LEAST(ROUND(SAFE_DIVIDE(AVAILABLE_INVENTORY, DRR), 1), 999) END AS DOH, CASE WHEN DRR = 0 THEN \'No Sales\' WHEN SAFE_DIVIDE(AVAILABLE_INVENTORY, DRR) < 7 THEN \'Critical\' WHEN SAFE_DIVIDE(AVAILABLE_INVENTORY, DRR) BETWEEN 7 AND 14 THEN \'Low\' WHEN SAFE_DIVIDE(AVAILABLE_INVENTORY, DRR) BETWEEN 14 AND 60 THEN \'Healthy\' ELSE \'Overstocked\' END AS STOCK_STATUS, ROUND( IFNULL( SAFE_DIVIDE(GMV_LAST_DAY, NULLIF(SOLD_QTY_LAST_DAY, 0)), BAU_ONLINE ) * AVAILABLE_INVENTORY, 2) AS INVENTORY_VALUE FROM DOH_BASE;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            